# Task: drive the new typed-coordinate entry in the Mutation tab and check that valid input moves the slider and each invalid input warns
# Reviewed by:
"""
Usage:
    python check_typed_coords.0.py <url>

Walks the live app: loads the tutorial genes, opens the Mutation tab, then for
each case types a pair of coordinates, presses "Set range" and records what the
interface does -- the slider range and region afterwards, or the warning text.
"""
import sys

from playwright.sync_api import sync_playwright

CASES = [
    # (system, from, to, what we expect to see)
    ("deepCRE window (1–3020)", "1001", "1500", "sets gTUR 1001-1500"),
    ("deepCRE window (1–3020)", "1", "1000", "sets gUR 1-1000"),
    ("deepCRE window (1–3020)", "0", "500", "warns: outside the window"),
    ("deepCRE window (1–3020)", "1", "3021", "warns: outside the window"),
    ("deepCRE window (1–3020)", "1400", "1600", "warns: N-padding"),
    ("deepCRE window (1–3020)", "900", "1100", "warns: spans two regions"),
    ("deepCRE window (1–3020)", "abc", "1500", "warns: whole number"),
    ("deepCRE window (1–3020)", "", "1500", "warns: whole number"),
    ("Genomic (1-based)", "20134844", "20135343", "sets gTUR via genomic"),
    ("Genomic (1-based)", "20,134,844", "20,135,343", "same, with thousands separators"),
    ("Genomic (1-based)", "1000000", "1000500", "warns: not inside the window"),
]


def state(page):
    """The slider's current range and the selected region."""
    main = page.locator('[data-testid="stMain"]')
    region = page.evaluate(
        """() => [...document.querySelectorAll('[data-testid="stMain"] label[data-baseweb="radio"]')]
             .filter(l => ['gUR','gTUR','gTDR','gDR'].includes(l.textContent.trim()))
             .find(l => l.querySelector('input').checked)?.textContent.trim()"""
    )
    thumbs = page.evaluate(
        """() => [...document.querySelectorAll('[data-testid="stMain"] [data-testid="stSlider"] [role="slider"]')]
             .map(s => s.getAttribute('aria-valuenow'))"""
    )
    return region, thumbs


def messages(page):
    return page.evaluate(
        """() => [...document.querySelectorAll('[data-testid="stMain"] [data-testid="stAlertContainer"]')]
             .map(a => a.textContent.trim()).filter(t => t)"""
    )


def main(url):
    with sync_playwright() as pw:
        b = pw.chromium.launch()
        page = b.new_page(viewport={"width": 1500, "height": 1100})
        page.set_default_timeout(120_000)
        page.goto(url, wait_until="networkidle")
        page.wait_for_timeout(9000)
        page.get_by_role("tab", name="Tutorial", exact=True).first.click()
        page.wait_for_timeout(4000)
        page.get_by_role("button", name="Load Tutorial Genes & Set Model").click()
        page.wait_for_timeout(15000)
        page.get_by_role("tab", name="Mutation", exact=True).first.click()
        page.wait_for_timeout(18000)

        main_area = page.locator('[data-testid="stMain"]')
        failures = 0
        for system, lo, hi, expectation in CASES:
            # The expander collapses on every rerun. Open it only when the
            # fields inside are actually hidden, or the click closes it again.
            field = page.locator('[data-testid="stMain"] input[aria-label="From"]')
            if field.count() == 0 or not field.first.is_visible():
                main_area.get_by_text("Type the coordinates instead").first.click()
                page.wait_for_timeout(1500)
            before = state(page)
            main_area.locator('label[data-baseweb="radio"]').filter(
                has_text=system).first.click()
            page.wait_for_timeout(2500)
            page.fill('[data-testid="stMain"] input[aria-label="From"]', lo)
            page.fill('[data-testid="stMain"] input[aria-label="To"]', hi)
            page.get_by_role("button", name="Set range").first.click()
            page.wait_for_timeout(6000)
            after = state(page)
            msgs = [m for m in messages(page)
                    if "Tutorial Shortcut" not in m and "Instructions" not in m]
            note = next((m for m in msgs if "Range set" in m or "outside" in m
                         or "N-padding" in m or "spans" in m
                         or "whole number" in m or "not inside" in m), "")
            # A valid range counts as applied when the app confirms it, not
            # only when the slider moves: a case may legitimately set the range
            # the previous case already left in place.
            if "warns" in expectation:
                ok = note.startswith("⚠️") or "⚠️" in note
            else:
                ok = "Range set" in note and before != after or "Range set" in note
            failures += 0 if ok else 1
            print(f"  {system.split()[0]:8s} {lo!r:>14} {hi!r:>12}  "
                  f"{'OK ' if ok else 'BAD'}  region/slider {after[0]} {after[1]}")
            print(f"      expected: {expectation}")
            print(f"      app said: {note[:150] or '(nothing)'}")
        b.close()
        print(f"\n{len(CASES) - failures} of {len(CASES)} cases behaved as expected")
        return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8502"))
